package com.oracle.banking.customer.controller;
import com.oracle.banking.customer.dto.CustomerDtos.*; import com.oracle.banking.customer.service.CustomerService; import com.oracle.banking.shared.response.ApiResponse; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/customers") public class CustomerController {private final CustomerService s;public CustomerController(CustomerService s){this.s=s;}@GetMapping("/me") ApiResponse<Response> me(Authentication a){return ApiResponse.success("Customer profile",s.own(a.getName()));}@PutMapping("/me") ApiResponse<Response> update(Authentication a,@Valid @RequestBody Update r){return ApiResponse.success("Customer profile updated",s.update(a.getName(),r));}@GetMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") ApiResponse<Response> byId(@PathVariable String id){return ApiResponse.success("Customer profile",s.byId(id));}}
